  ('Weekend Plans', '{"prompt":"מה קונים?","options":["Fish and rice","Cake and juice","Apples and bread","Milk and eggs"],"correctIndex":2}', 3),
  ('At School', '{"prompt":"באיזה עמוד פותחים את הספר?","options":["Page five","Page ten","Page twelve","Page two"],"correctIndex":1}', 2),
