-- Check: clips from this seed, and their questions.
select
  (select count(*) from public.listening_clips where title_en in ('At the Bakery', 'Meeting in the Park', 'The Weather Today', 'After School', 'A Product Launch Briefing', 'A Lecture on Sleep and Memory', 'A Voicemail from a Contractor', 'A Radio Debate on Rent Control', 'A Talk on Translation', 'An Interview on AI and Accountability')) as new_clips,
  (select count(*) from public.exercises e join public.listening_clips lc on lc.id = e.listening_clip_id
     where e.type = 'mcq' and lc.title_en in ('At the Bakery', 'Meeting in the Park', 'The Weather Today', 'After School', 'A Product Launch Briefing', 'A Lecture on Sleep and Memory', 'A Voicemail from a Contractor', 'A Radio Debate on Rent Control', 'A Talk on Translation', 'An Interview on AI and Accountability', 'Ordering Coffee', 'A Phone Call', 'Weekend Plans', 'At School', 'At the Supermarket')) as listening_questions;
